import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry gelu_tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u64 n
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<8>;
    .reg .b64 %rd<12>;
    .reg .f32 %f<24>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u64 %rd3, [n];

    mov.b32 %r1, %ctaid.x;
    mov.b32 %r2, %ntid.x;
    mov.b32 %r3, %tid.x;

    cvt.u64.u32 %rd4, %r1;
    cvt.u64.u32 %rd5, %r2;
    mul.lo.u64 %rd4, %rd4, %rd5;
    cvt.u64.u32 %rd5, %r3;
    add.u64 %rd4, %rd4, %rd5;

    setp.ge.u64 %p1, %rd4, %rd3;
    @%p1 bra DONE;

    shl.b64 %rd5, %rd4, 2;
    add.u64 %rd6, %rd1, %rd5;
    ld.global.f32 %f1, [%rd6];

    mul.f32 %f2, %f1, %f1;
    mul.f32 %f3, %f2, %f1;
    mov.f32 %f4, 0.044715;
    fma.rn.f32 %f5, %f3, %f4, %f1;
    mov.f32 %f6, 0.7978845608028654;
    mul.f32 %f5, %f5, %f6;

    abs.f32 %f6, %f5;
    mov.f32 %f7, -2.8853900817779268;
    mul.f32 %f7, %f6, %f7;
    ex2.approx.f32 %f8, %f7;

    mov.f32 %f9, 1.0;
    sub.f32 %f10, %f9, %f8;
    add.f32 %f11, %f9, %f8;
    div.rn.f32 %f12, %f10, %f11;

    mov.f32 %f13, 0.0;
    setp.lt.f32 %p2, %f5, %f13;
    neg.f32 %f14, %f12;
    selp.f32 %f15, %f14, %f12, %p2;

    add.f32 %f16, %f15, %f9;
    mul.f32 %f17, %f16, %f1;
    mov.f32 %f18, 0.5;
    mul.f32 %f19, %f17, %f18;

    add.u64 %rd7, %rd2, %rd5;
    st.global.f32 [%rd7], %f19;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("gelu_tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        out = torch.empty(x.shape, device=x.device, dtype=x.dtype)
        n = x.numel()
        if n == 0:
            return out
        module = _get_ptx_module()
        block = 256
        grid = ((n + block - 1) // block, 1, 1)
        module.launch(
            "gelu_tanh_kernel",
            grid=grid,
            block=(block, 1, 1),
            arguments=[x, out, u64(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

